-- Version publique : telephones et emails remplaces par des valeurs de demonstration.

SET DEFINE OFF
SET SERVEROUTPUT ON SIZE UNLIMITED
SET FEEDBACK OFF
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK

-- Le MLD autorise la reference facultative au circuit complet.
-- CodeCI_Est_Complete est NULL lorsqu'aucun circuit complet n'est rattache.
-- NomCI et NomAC doivent accueillir les libelles complets sans troncature.
-- Remarque : les ALTER TABLE effectuent un COMMIT implicite sous Oracle.
DECLARE
  v_nullable USER_TAB_COLUMNS.NULLABLE%TYPE;
  v_char_used USER_TAB_COLUMNS.CHAR_USED%TYPE;
  v_data_length NUMBER;
  v_char_length NUMBER;
  PROCEDURE agrandir_si_necessaire(p_table VARCHAR2, p_col VARCHAR2) IS
  BEGIN
    SELECT CHAR_USED, DATA_LENGTH, CHAR_LENGTH
      INTO v_char_used, v_data_length, v_char_length
      FROM USER_TAB_COLUMNS
     WHERE TABLE_NAME = p_table AND COLUMN_NAME = p_col;
    IF (v_char_used = 'C' AND v_char_length < 40)
       OR (NVL(v_char_used, 'B') = 'B' AND v_data_length < 40) THEN
      EXECUTE IMMEDIATE 'ALTER TABLE ' || p_table ||
                        ' MODIFY (' || p_col || ' VARCHAR2(40 CHAR))';
      DBMS_OUTPUT.PUT_LINE('Colonne elargie : ' || p_table || '.' || p_col);
    END IF;
  END;
BEGIN
  SELECT NULLABLE INTO v_nullable FROM USER_TAB_COLUMNS
   WHERE TABLE_NAME = 'CIRCUITS' AND COLUMN_NAME = 'CODECI_EST_COMPLETE';
  IF v_nullable = 'N' THEN
    EXECUTE IMMEDIATE 'ALTER TABLE CIRCUITS MODIFY (CodeCI_Est_Complete NULL)';
    DBMS_OUTPUT.PUT_LINE('CIRCUITS.CodeCI_Est_Complete rendu nullable.');
  END IF;
  agrandir_si_necessaire('CIRCUITS', 'NOMCI');
  agrandir_si_necessaire('ACTIVITE', 'NOMAC');
END;
/

