INSERT ALL
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (1, 'Médina de Tunis', 'historique', 'Vieille ville classée à l’UNESCO, avec ses ruelles, ses souks et ses palais.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (2, 'Ruines de Carthage', 'historique', 'Vestiges de la cité punique puis romaine : thermes d’Antonin, port et tophet.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (3, 'Amphithéâtre d’El Jem', 'historique', 'Grand amphithéâtre romain du IIIe siècle, l’un des mieux conservés au monde.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (4, 'Grande Mosquée de Kairouan', 'religieux', 'Premier lieu saint du Maghreb, fondé en 670, avec sa cour et son minaret massif.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (5, 'Dunes de Douz', 'paysage', 'Porte du Sahara tunisien, balade dans l’erg au coucher du soleil.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (6, 'Souk de Houmt Souk', 'commerce', 'Marché animé de Djerba : poteries, bijoux, épices et artisanat.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (7, 'Sidi Bou Saïd', 'autre', 'Village blanc et bleu perché au-dessus de la baie de Tunis.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (8, 'Médina de Fès', 'historique', 'Plus grande zone piétonne urbaine du monde, avec ses tanneries et ses medersas.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (9, 'Place Jemaa el-Fna', 'commerce', 'Place de Marrakech avec ses étals, ses conteurs et ses musiciens.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (10, 'Mosquée Hassan II', 'religieux', 'Mosquée de Casablanca bâtie face à l’océan, avec l’un des plus hauts minarets du monde.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (11, 'Kasbah d’Aït Ben Haddou', 'historique', 'Village fortifié en terre crue sur l’ancienne route des caravanes.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (12, 'Gorges du Todra', 'paysage', 'Falaises de plus de 300 mètres de haut au cœur du Haut Atlas.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (13, 'Dunes de Merzouga', 'paysage', 'Grand erg de sable orange, nuit sous tente et lever du soleil sur les dunes.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (14, 'Ville bleue de Chefchaouen', 'autre', 'Village du Rif aux ruelles peintes en bleu, au pied des montagnes.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (15, 'Acropole d’Athènes', 'historique', 'Colline du Parthénon, symbole de la Grèce antique.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (16, 'Monastères des Météores', 'religieux', 'Monastères byzantins perchés sur des piliers de roche en Thessalie.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (17, 'Site de Delphes', 'historique', 'Sanctuaire d’Apollon et siège de l’oracle dans l’Antiquité.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (18, 'Village d’Oia à Santorin', 'autre', 'Village aux maisons blanches et aux dômes bleus face à la caldeira.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (19, 'Marché de Monastiraki', 'commerce', 'Marché aux puces d’Athènes : souvenirs, antiquités et cuisine de rue.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (20, 'Colisée de Rome', 'historique', 'Amphithéâtre de l’époque flavienne, pouvant accueillir environ 50 000 spectateurs.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (21, 'Duomo de Florence', 'religieux', 'Cathédrale Santa Maria del Fiore et sa coupole de Brunelleschi.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (22, 'Grand Canal de Venise', 'paysage', 'Principale voie d’eau de la ville, bordée de palais, avec le pont du Rialto.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (23, 'Volcan Etna', 'paysage', 'Plus haut volcan actif d’Europe, ascension jusqu’aux cratères sommitaux.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (24, 'Temples d’Agrigente', 'historique', 'Temples doriens grecs de Sicile, dont le temple de la Concorde.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (25, 'Alhambra de Grenade', 'historique', 'Palais et forteresse nasrides, chef-d’œuvre de l’art hispano-mauresque.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (26, 'Mezquita de Cordoue', 'religieux', 'Mosquée-cathédrale connue pour sa forêt de colonnes et d’arcs bicolores.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (27, 'Sagrada Familia', 'religieux', 'Basilique de Gaudí à Barcelone, en construction depuis 1882.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (28, 'Mercado de la Boqueria', 'commerce', 'Marché couvert des Ramblas, avec produits frais, jambons et fruits.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (29, 'Sainte-Sophie', 'religieux', 'Ancienne basilique byzantine d’Istanbul, devenue mosquée.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (30, 'Grand Bazar d’Istanbul', 'commerce', 'Un des plus grands marchés couverts du monde, avec plus de 4 000 boutiques.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (31, 'Cheminées de Cappadoce', 'paysage', 'Formations rocheuses en forme de cônes et maisons troglodytes.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (32, 'Site d’Éphèse', 'historique', 'Cité antique grecque et romaine : bibliothèque de Celsus et grand théâtre.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (33, 'Pyramides de Gizeh', 'historique', 'Pyramides de Khéops, Khéphren et Mykérinos, avec le Sphinx.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (34, 'Temple de Karnak', 'religieux', 'Immense complexe de temples dédié à Amon-Rê, à Louxor.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (35, 'Vallée des Rois', 'historique', 'Nécropole des pharaons du Nouvel Empire, creusée dans la roche.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (36, 'Cité des Arts et des Sciences', 'autre', 'Ensemble culturel et scientifique contemporain de Valence, avec musée, aquarium et architecture futuriste.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (37, 'Marché central de Valence', 'commerce', 'Halles historiques de Valence, réputées pour leurs étals de produits frais et spécialités locales.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (38, 'Château de Santa Bárbara', 'historique', 'Forteresse dominant Alicante et la côte méditerranéenne, offrant un panorama sur la ville et la mer.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (39, 'Palais de Dioclétien', 'historique', 'Résidence de l’empereur romain au cœur de la vieille ville de Split.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (40, 'Remparts de Dubrovnik', 'historique', 'Fortifications médiévales de la ville fortifiée, avec vue sur l’Adriatique.')
  INTO SITES (CodeS, NomS, TypeS, DescripS) VALUES (41, 'Lacs de Plitvice', 'paysage', 'Parc national de seize lacs reliés par des cascades.')
SELECT 1 FROM DUAL;

