--CONTROLES ET VALIDATION AVANT COMMIT
DECLARE
  v_nb NUMBER;
  v_ca NUMBER;
  PROCEDURE assert_count(p_table VARCHAR2, p_attendu NUMBER) IS
  BEGIN
    EXECUTE IMMEDIATE 'SELECT COUNT(*) FROM ' || p_table INTO v_nb;
    IF v_nb <> p_attendu THEN
      RAISE_APPLICATION_ERROR(-20001, p_table || ': ' || v_nb ||
                              ' lignes (attendu ' || p_attendu || ')');
    END IF;
    DBMS_OUTPUT.PUT_LINE(RPAD(p_table,16) || TO_CHAR(v_nb));
  END;
  PROCEDURE assert_zero(p_valeur NUMBER, p_message VARCHAR2) IS
  BEGIN
    IF p_valeur <> 0 THEN
      RAISE_APPLICATION_ERROR(-20002, p_message || ': ' || p_valeur);
    END IF;
  END;
BEGIN
  DBMS_OUTPUT.PUT_LINE('Verification des volumes :');
  assert_count('CLIENTS', 601);
  assert_count('AEROPORTS_DEP', 29);
  assert_count('CIRCUITS', 22);
  assert_count('HOTELS', 133);
  assert_count('ACTIVITE', 20);
  assert_count('SITES', 41);
  assert_count('MOIS', 12);
  assert_count('PAYS', 8);
  assert_count('ZONE_GEO', 8);
  assert_count('GUIDES', 43);
  assert_count('LANGUE', 11);
  assert_count('MAJORATION', 213);
  assert_count('CHOIX', 218);
  assert_count('RESERVER', 800);
  assert_count('LOGER', 154);
  assert_count('ANIMATIONS', 40);
  assert_count('VALIDITE', 16);
  assert_count('REALISER', 133);
  assert_count('VISITER', 63);
  assert_count('AVIS', 96);
  assert_count('SITUER', 38);
  assert_count('ACCOMPAGNER', 174);
  assert_count('PRATIQUER', 141);
  SELECT COUNT(*) INTO v_nb FROM RESERVER r
   WHERE NOT EXISTS (SELECT 1 FROM MAJORATION m
           WHERE m.CodeA = r.CodeA AND m.CodeCI = r.CodeCI
             AND m.DateDepartM = r.DateDepartR);
  assert_zero(v_nb, 'Reservations sans depart propose');

  SELECT COUNT(*) INTO v_nb FROM CHOIX c
   WHERE NOT EXISTS (SELECT 1 FROM MAJORATION m
           WHERE m.CodeA = c.CodeA AND m.CodeCI = c.CodeCI
             AND m.DateDepartM = c.DateDepartC);
  assert_zero(v_nb, 'Preselections sans depart propose');

  SELECT COUNT(*) INTO v_nb FROM RESERVER
   WHERE DateResa > DateDepartR OR NbPers <= 0;
  assert_zero(v_nb, 'Reservations avec dates ou effectifs invalides');

  SELECT COUNT(*) INTO v_nb FROM
   (SELECT r.CodeCI, r.DateDepartR
      FROM RESERVER r JOIN CIRCUITS c ON c.CodeCI = r.CodeCI
     GROUP BY r.CodeCI, r.DateDepartR, c.NbPersMax
    HAVING SUM(r.NbPers) > c.NbPersMax);
  assert_zero(v_nb, 'Departs depassant NbPersMax (tous aeroports)');

  SELECT COUNT(*) INTO v_nb FROM
   (SELECT m.CodeCI, m.DateDepartM FROM MAJORATION m
    GROUP BY m.CodeCI, m.DateDepartM
    MINUS
    SELECT g.CodeCI, g.DateDepartA FROM ACCOMPAGNER g);
  assert_zero(v_nb, 'Circuit/date sans guide');

  SELECT COUNT(*) INTO v_nb FROM
   (SELECT CodeCI, DateDepartA FROM ACCOMPAGNER
    GROUP BY CodeCI, DateDepartA HAVING COUNT(*) > 1);
  assert_zero(v_nb, 'Affectations multiples sur circuit/date');

  SELECT COUNT(*) INTO v_nb FROM CIRCUITS c
   WHERE (SELECT COUNT(*) FROM LOGER l WHERE l.CodeCI = c.CodeCI) <> 7;
  assert_zero(v_nb, 'Circuits sans exactement 7 nuits/hotels');

  SELECT COUNT(*) INTO v_nb FROM
   (SELECT a.CodeC FROM RESERVER a JOIN RESERVER b
        ON a.CodeC = b.CodeC
       AND a.DateDepartR < b.DateDepartR
       AND b.DateDepartR < a.DateDepartR + 7);
  assert_zero(v_nb, 'Voyages clients chevauchants');

  SELECT COUNT(*) INTO v_nb FROM
   (SELECT a.CodeG FROM ACCOMPAGNER a JOIN ACCOMPAGNER b
        ON a.CodeG = b.CodeG
       AND a.DateDepartA < b.DateDepartA
       AND b.DateDepartA < a.DateDepartA + 7);
  assert_zero(v_nb, 'Voyages guides chevauchants');

  SELECT COUNT(*) INTO v_nb FROM
   (SELECT CodeP FROM AVIS GROUP BY CodeP HAVING COUNT(*) <> 12);
  assert_zero(v_nb, 'Pays sans 12 mois de climat');

  SELECT SUM(r.NbPers * (c.PrixBase + m.MontantMaj)) INTO v_ca
    FROM RESERVER r JOIN CIRCUITS c ON c.CodeCI = r.CodeCI
      JOIN MAJORATION m ON m.CodeA = r.CodeA
                        AND m.CodeCI = r.CodeCI
                        AND m.DateDepartM = r.DateDepartR;
  IF v_ca <> 1879485 THEN
    RAISE_APPLICATION_ERROR(-20003, 'Chiffre affaires inattendu : ' || v_ca);
  END IF;
  DBMS_OUTPUT.PUT_LINE('Chiffre d''affaires : ' || TO_CHAR(v_ca) || ' EUR');
  DBMS_OUTPUT.PUT_LINE('Tous les controles principaux sont valides.');
END;
/

COMMIT;
